// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amt) public {
        vm.assume(actor != address(0));
        amt = bound(amt, 0, 1 ether);

        vm.deal(actor, amt);
        vm.prank(actor);
        c.addToBalance{value: amt}();

        uint balForActor = c.getBalance(actor);
        uint balForZero = c.getBalance(address(0));

        vm.assume(amt > 0);

        assertTrue(balForActor != balForZero);
    }
}
